import { defineConfig } from "vitest/config";

export default defineConfig({
  test: {
    pool: "forks",
    maxWorkers: "50%",
    include: ["**/tests/**/*.test.ts", "**/*.test.ts"],
    exclude: [
      "**/dist/**",
      "**/node_modules/**",
      "**/.claude/worktrees/**",
      "bin/tests/**",
    ],
    coverage: {
      provider: "v8",
      include: ["packages/*/src/**/*.ts"],
      exclude: ["**/index.ts", "**/*.d.ts"],
      // json emits coverage-final.json — the v8 text table hides 100%-covered
      // files, so the JSON is the authoritative per-file record.
      reporter: ["text", "html", "json"],
      thresholds: {
        lines: 90,
        functions: 83,
        branches: 80,
        statements: 89,
        // perFile: true gates each file individually, not just the aggregate.
        perFile: true,
      },
    },
  },
});

