import { describe, expect, it, vi } from "vitest";
import { authenticate } from "../src/core/auth/index.js";

// DEFECT: MOCK_TOKEN is a plain file-scope const. vi.mock is hoisted to the
// top of the file by Vitest and runs before any const initializers, so
// MOCK_TOKEN is not yet initialized when the factory executes.
const MOCK_TOKEN = "test-token-123";

vi.mock("../src/core/auth/index.js", () => ({
  authenticate: vi.fn().mockResolvedValue(MOCK_TOKEN),
}));

describe("authenticate", () => {
  it("returns the mocked token", async () => {
    const result = await authenticate("user", "pass");
    expect(result).toBe(MOCK_TOKEN);
  });
});
